def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(length, separators):
        parts = []
        start = 0
        for i in separators:
            if start < i:
                parts.append((start, i))
            start = i + 1
        if start < length:
            parts.append((start, length))
        return parts

    rows, cols = spans(h, sep_rows), spans(w, sep_cols)
    out = []
    for r0, r1 in rows:
        line = []
        for c0, c1 in cols:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            counts = {}
            for v in vals:
                counts[v] = counts.get(v, 0) + 1
            background = max(counts, key=counts.get)
            marks = len(vals) - counts[background]
            line.append(1 if marks >= 2 else background)
        out.append(line)
    return out

